class TestConstructor:
    """Validate DockerRuntime initialization paths."""

    def test_constructor_success(self, mock_docker_client):
        """Constructor should initialize with valid socket path."""
        with patch("docker.DockerClient", return_value=mock_docker_client) as mock_factory:
            rt = DockerRuntime(socket_path="/var/run/docker.sock")
            mock_factory.assert_called_once_with(base_url="unix:///var/run/docker.sock")
            assert rt.client is mock_docker_client
            assert rt.socket_path == "/var/run/docker.sock"

    def test_constructor_default_socket(self, mock_docker_client):
        """Constructor should use default socket when not specified."""
        with patch("docker.DockerClient", return_value=mock_docker_client) as mock_factory:
            rt = DockerRuntime()
            mock_factory.assert_called_once_with(base_url="unix:///var/run/docker.sock")
            assert rt.socket_path == "/var/run/docker.sock"

    def test_constructor_socket_failure(self):
        """Constructor should raise ContainerExecutionError on socket failure."""
        with patch("docker.DockerClient", side_effect=Exception("Cannot connect")):
            with pytest.raises(ContainerExecutionError) as exc_info:
                DockerRuntime(socket_path="/tmp/nonexistent.sock")
            assert "Cannot connect" in str(exc_info.value)

    def test_constructor_invalid_socket_path(self):
        """Constructor should reject empty or malformed socket paths."""
        with pytest.raises(ValueError):
            DockerRuntime(socket_path="")
        with pytest.raises(ValueError):
            DockerRuntime(socket_path=None)


