class TestRunCommandFailures:
    """Validate error handling for container execution failures."""

    def test_run_command_container_error(self, runtime):
        """run_command should raise ContainerExecutionError on container failure."""
        runtime.client.containers.run.side_effect = Exception("Container crashed")

        with pytest.raises(ContainerExecutionError) as exc_info:
            runtime.run_command(image="bad-image", command=["boom"])
        assert "Container crashed" in str(exc_info.value)

    def test_run_command_timeout(self, runtime, mock_container):
        """run_command should raise ContainerExecutionError on timeout."""
        runtime.client.containers.run.return_value = mock_container
        mock_container.wait.side_effect = Exception("Timeout exceeded")

        with pytest.raises(ContainerExecutionError) as exc_info:
            runtime.run_command(image="alpine", command=["sleep", "100"], timeout=1)
        assert "Timeout" in str(exc_info.value)

    def test_run_command_nonzero_exit(self, runtime, mock_container):
        """run_command should raise ContainerExecutionError on non-zero exit."""
        runtime.client.containers.run.return_value = mock_container
        mock_container.wait.return_value = {"StatusCode": 1}

        with pytest.raises(ContainerExecutionError) as exc_info:
            runtime.run_command(image="alpine", command=["false"])
        assert "exit code 1" in str(exc_info.value).lower()

    def test_run_command_resource_constraint(self, runtime):
        """run_command should raise ResourceConstraintError on resource limits."""
        runtime.client.containers.run.side_effect = Exception("Out of memory")

        with pytest.raises(ResourceConstraintError) as exc_info:
            runtime.run_command(image="heavy", command=["run"], memory_limit="1g")
        assert "Out of memory" in str(exc_info.value)

    def test_run_command_cleanup_on_failure(self, runtime, mock_container):
        """run_command should remove container on wait failure."""
        runtime.client.containers.run.return_value = mock_container
        mock_container.wait.side_effect = Exception("Container died")

        with pytest.raises(ContainerExecutionError):
            runtime.run_command(image="alpine", command=["boom"])

        mock_container.remove.assert_called_once_with(force=True)

    def test_run_command_cleanup_on_nonzero_exit(self, runtime, mock_container):
        """run_command should remove container on non-zero exit."""
        runtime.client.containers.run.return_value = mock_container
        mock_container.wait.return_value = {"StatusCode": 2}

        with pytest.raises(ContainerExecutionError):
            runtime.run_command(image="alpine", command=["exit", "2"])

        mock_container.remove.assert_called_once_with(force=True)


