class TestDetachedCleanup:
    """Validate container cleanup behavior for detached execution."""

    def test_success_removes_container(self, runtime, mock_container):
        """run_command should remove container after successful execution."""
        runtime.client.containers.run.return_value = mock_container
        mock_container.wait.return_value = {"StatusCode": 0}

        runtime.run_command(image="alpine", command=["true"])

        mock_container.remove.assert_called_once_with(force=False)

    def test_failure_removes_container_force(self, runtime, mock_container):
        """run_command should force-remove container on failure."""
        runtime.client.containers.run.return_value = mock_container
        mock_container.wait.return_value = {"StatusCode": 1}

        with pytest.raises(ContainerExecutionError):
            runtime.run_command(image="alpine", command=["false"])

        mock_container.remove.assert_called_once_with(force=True)

    def test_exception_during_remove(self, runtime, mock_container):
        """Cleanup failure should not mask original error."""
        runtime.client.containers.run.return_value = mock_container
        mock_container.wait.return_value = {"StatusCode": 1}
        mock_container.remove.side_effect = Exception("Remove failed")

        with pytest.raises(ContainerExecutionError) as exc_info:
            runtime.run_command(image="alpine", command=["false"])

        assert "exit code 1" in str(exc_info.value).lower()

    def test_no_remove_on_run_failure(self, runtime):
        """If container never created, no remove should be attempted."""
        runtime.client.containers.run.side_effect = Exception("Create failed")

        with pytest.raises(ContainerExecutionError):
            runtime.run_command(image="bad", command=["x"])

        # No container object to remove
        assert not hasattr(runtime.client.containers, "remove_called")


